                mov     edx, [ecx]
                add     ecx, 4
                ;mov    [ebp+tmp2], eax
                mov     [eax], edx
                ;mov    eax, [ecx]      ; high dword of 'opx->offset'
                ;mov    ecx, [ebp+tmp2]
                ;mov    [ecx], edx
                ;add    ecx, 4          ; high dword of 'data->toffset' address
                ;mov    [ecx], eax
