; ---------------------------------------------------------------------------
; Function: jmp_match
;
; Description:
;
; C Declaration:
;         static bool jmp_match(int32_t segment, int64_t offset, int bits,
;                               insn * ins, const struct itemplate *temp)
;
; Input (Stack): [EBP+8]  = segment
;                [EBP+12] = offset (low dword)
;                [EBP+16] = offset (high dword)
;                [EBP+20] = bits
;                [EBP+24] = *ins
;                [EBP+28] = *temp
;
; Output [EAX]: 1 or 0
;
; Modified Registers: EAX, ECX, EDX
; ---------------------------------------------------------------------------

%assign is_byte  -14h
%assign c        -0Dh
%assign _code    -0Ch
%assign isize    -8
%assign isize_h  -4
%assign _segment  8
%assign _offset   0Ch
%assign _offset_h 10h
%assign _bits     14h
%assign ins       18h
%assign temp      1Ch

jmp_match:
                push    ebp
                mov     ebp, esp        ; int64_t isize;
                sub     esp, 20         ; const uint8_t *code = temp->code;
                ;nop                    ; uint8_t c = code[0];
                                        ; bool is_byte;
                mov     eax, [ebp+temp] ; if (((c & ~1) != 0370) || (ins->oprs[0].type & STRICT))
                add     eax, 60         ; (temp->code address = temp + 60)
                mov     ecx, [eax]
                mov     [ebp+_code], ecx
                ;mov    eax, [ebp+_code]
                ;movzx  ecx, byte [eax] ; c = code[0];
                ;mov    [ebp+c], cl
                movzx   eax, byte [ecx]
                mov     [ebp+c], al        
                ;movzx  eax, [ebp+c]
                ;and    eax, 0FFFFFFFEh ; c & ~1  (not 0001b = 1110b)
                and     al, 0FEh 
                ;cmp    eax, 248        ; 370o ; 0F8h
