                jnz     jm_3            ; (true)
                mov     eax, [ebp+ins]  ; or (ins->oprs[0].type & STRICT)
                                        ; (operand->type = operand + 0) /// oprs = operand structure
                                        ; (ins->oprs = ins + 48)
                add     eax, 48
                mov     ecx, [eax]      ; (operand structure address)
                add     eax, 4          ; typedef uint64_t opflags_t;
                                        ; opflags_t type; /* type of operand */
                mov     edx, [eax]      ; high dword of 'operand->type' (is not used here)
                and     ecx, 64         ; and  ecx, STRICT /// STRICT = 64 (1<<6)
                                        ;
                                        ; #define STRICT GEN_MODIFIER(2) /* do not optimize this operand */
                                        ; #define GEN_MODIFIER(bit) OP_GENBIT(bit, MODIFIER_SHIFT)
                                        ; #define MODIFIER_SHIFT (4)
                                        ; #define OP_GENBIT(bit, shift) (UINT64_C(1) << ((shift) + (bit)))
                ;mov    eax, 0
                ;cmp    eax, 0
                ;jnz    jm_1
                ;cmp    ecx, 0          ; if (condition)
                jz      jm_2            ; = 0 -> (continue)

;jm_1:                                  ; ...
                ;jmp    jm_3            ; = 1 -> return false;
; ---------------------------------------------------------------------------

;jm_2:                                   ; ...
                ;jmp    jm_4
; ---------------------------------------------------------------------------

jm_1:
jm_3:                                   ; ...
                mov     eax, 0          ; return false;
                jmp     jm_15
; ---------------------------------------------------------------------------

jm_2:
jm_4:                                   ; ...
                mov     eax, [optimizing] ; if (!optimizing.level
                                        ;       || (optimizing.flag & OPTIM_DISABLE_JMP_MATCH))
                cmp     eax, 0          ; struct optimization {
                                        ;     int level;
                                        ;     int flag;
                                        ; };
                ;jz     jm_5            ; return false;
                jz      jm_15
                mov     eax, [optimizing+4] ; (optimizing.flag = optimizing + 4)
                and     eax, 1
                ;cmp    eax, 0
                ;jnz    jm_5            ; return false;
                ;jmp    jm_6
                jz      jm_6
; ---------------------------------------------------------------------------

jm_5:                                   ; ...
                ;mov    eax, 0          ; return false;
                mov     al, 0 
                jmp     jm_15
; ---------------------------------------------------------------------------

jm_6:                                   ; ...
                mov     eax, [optimizing] ; (optimizing.level = optimizing + 0)
                cmp     eax, 0          ; if (optimizing.level < 0 && c == 0371)
                jge     jm_7
                ;movzx  eax, [ebp+c]
                mov     al, [ebp+c] 
                ;cmp    eax, 249        ; 0F9h ; 371o
                cmp     al, 249
                jnz     jm_7            ; (if condition is false, continue)
                mov     eax, 0
                jmp     jm_15           ; (if condition is true) return false;
; ---------------------------------------------------------------------------

jm_7:                                   ; ...
                mov     eax, [ebp+temp] ; isize = calcsize(segment, offset, bits, ins, temp);
                push    eax
                mov     eax, [ebp+ins]
                push    eax
                mov     eax, [ebp+_bits]
                push    eax
                mov     eax, [ebp+_offset]
                mov     ecx, [ebp+_offset_h]
                push    ecx
                push    eax
                mov     eax, [ebp+_segment]
                push    eax
                call    calcsize
