                mov     [ebp+isize], eax
                mov     [ebp+isize_h], edx
                mov     eax, [ebp+ins]  ; if (ins->oprs[0].opflags & OPFLAG_UNKNOWN)
                ;add    eax, 48         ; (ins->oprs = ins + 48)
                ;add    eax, 56         ; (operand->opflags = operand + 56)
                add     eax, 48+56 
