                and     ecx, 4          ; & OPFLAG_UNKNOWN
                ;cmp    ecx, 0
                jz      jm_8
                mov     eax, 1          ; /* Be optimistic in pass 1 */
                jmp     jm_15           ; return true;
; ---------------------------------------------------------------------------

jm_8:                                   ; ...
                mov     eax, [ebp+ins]  ; if (ins->oprs[0].segment != segment)
                ;add    eax, 48         ; (ins->oprs = ins + 48)
                ;add    eax, 32         ; (operand->segment = operand + 32)
                add     eax, 48+32
                mov     ecx, [eax]
                mov     eax, [ebp+_segment]
                cmp     ecx, eax
                jz      jm_9
                mov     eax, 0
                jmp     jm_15           ; return false;
; ---------------------------------------------------------------------------

jm_9:                                   ; /* isize is delta */
                mov     eax, [ebp+ins]  ; isize = ins->oprs[0].offset - offset - isize;
                ;add    eax, 48
                ;add    eax, 40         ; (operand->offset = operand + 40)
                                        ; /// NOTE: 8 byte aligned by the compiler!
                                        ;    (after 'operand->segment' at 'operand + 32')
                add     eax, 48+40
                mov     ecx, [eax]
                add     eax, 4
                mov     edx, [eax]
                mov     eax, [ebp+_offset]
                sub     ecx, eax
                mov     eax, [ebp+_offset_h]
                sbb     edx, eax
                mov     eax, [ebp+isize]
                sub     ecx, eax
                mov     eax, [ebp+isize_h]
                sbb     edx, eax
                mov     [ebp+isize], ecx
                mov     [ebp+isize_h], edx
                                           ; /* is it byte size? */
                ;mov    eax, [ebp+isize_h] ; is_byte = (isize >= -128 && isize <= 127)
                ;cmp    eax, 0FFFFFFFFh
                cmp     edx, 0FFFFFFFFh
                jl      jm_12
                jnz     jm_10
                mov     eax, [ebp+isize]
                cmp     eax, 0FFFFFF80h ; -128
                jb      jm_12

jm_10:                                  ; ...
                mov     eax, [ebp+isize_h]
                cmp     eax, 0
                jg      jm_12
                jnz     jm_11
                mov     eax, [ebp+isize]
                cmp     eax, 127
                ja      jm_12

jm_11:                                  ; ...
                mov     eax, 1          ; true
                jmp     short jm_13
; ---------------------------------------------------------------------------

jm_12:                                  ; ...
                mov     eax, 0          ; false

jm_13:                                  ; ...
                mov     [ebp+is_byte], eax
                ;mov    eax, [ebp+is_byte]
                cmp     eax, 0          ; if (is_byte && c == 0371 && ins->prefixes[PPS_REP] == P_BND) {
                ;jz     jm_14
                jz      jm_15
                ;movzx  eax, [ebp+c]
                mov     al, [ebp+c]
                ;cmp    eax, 249        ; 371o ; 0F9h
                cmp     al, 249
                jnz     jm_14
                mov     eax, [ebp+ins]  ; PPS_REP = 1
                ;add    eax, 4          ; (ins->prefixes = ins + 4) /// prefixes[MAXPREFIX]
                ;add    eax, 4          ; insn->prefixes[1]
                                        ; insn structure, offset 4 to 32 (array, 7 integers)
                                        ; ((prefixes[1] is at offset 9 of the structure))
                add     eax, 8 
