                ;add    eax, 4          ; ins->prefixes[1]
                mov     ecx, 0          ; P_none = 0
                mov     [eax], ecx
                mov     eax, A_34       ; "jmp short does not init bnd regs - bnd "...
                push    eax
                mov     eax, 0E102h     ; ERR_WARNING | WARN_BND | ERR_PASS2
                                        ;    0002h       0E000h      0100h
                push    eax
                call    nasm_error      ; nasm_error(ERR_WARNING | WARN_BND | ERR_PASS2 ,
                                        ;   "jmp short does not init bnd regs - bnd prefix dropped.");
                add     esp, 8

jm_14:                                  ; ...
                mov     eax, [ebp+is_byte] ; return is_byte;

jm_15:                                  ; ...
                leave
                retn


